package appeng.core.sync.packets;

import appeng.core.sync.BasePacket;
import appeng.core.sync.network.NetworkHandler;
import appeng.core.sync.packets.CompassResponsePacket;
import appeng.server.services.compass.CompassService;
import io.netty.buffer.Unpooled;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.ChunkPos;

public class CompassRequestPacket
extends BasePacket {
    final long attunement;
    final int cx;
    final int cz;
    final int cdy;

    public CompassRequestPacket(FriendlyByteBuf stream) {
        this.attunement = stream.readLong();
        this.cx = stream.readInt();
        this.cz = stream.readInt();
        this.cdy = stream.readInt();
    }

    public CompassRequestPacket(long attunement, int cx, int cz, int cdy) {
        FriendlyByteBuf data = new FriendlyByteBuf(Unpooled.buffer());
        data.writeInt(this.getPacketID());
        this.attunement = attunement;
        data.writeLong(this.attunement);
        this.cx = cx;
        data.writeInt(this.cx);
        this.cz = cz;
        data.writeInt(this.cz);
        this.cdy = cdy;
        data.writeInt(this.cdy);
        this.configureWrite(data);
    }

    @Override
    public void serverPacketData(ServerPlayer player) {
        ChunkPos pos = new ChunkPos(this.cx, this.cz);
        CompassService.Result result = CompassService.getDirection(player.m_284548_(), pos, 174);
        CompassResponsePacket responsePacket = new CompassResponsePacket(this, result.hasResult(), result.spin(), result.radians());
        NetworkHandler.instance().sendTo(responsePacket, player);
    }
}

