public class AEPatternDecoder
implements IPatternDetailsDecoder {
    public static final AEPatternDecoder INSTANCE = new AEPatternDecoder();

    @Override
    public boolean isEncodedPattern(ItemStack stack) {
        return stack.m_41720_() instanceof EncodedPatternItem;
    }

    @Override
    @Nullable
    public IPatternDetails decodePattern(AEItemKey what, Level level) {
        Item item;
        if (level == null || !((item = what.getItem()) instanceof EncodedPatternItem)) {
            return null;
        }
        EncodedPatternItem encodedPatternItem = (EncodedPatternItem)item;
        return encodedPatternItem.decode(what, level);
    }

    @Override
    @Nullable
    public IPatternDetails decodePattern(ItemStack what, Level level, boolean tryRecovery) {
        Item item;
        if (level == null || !((item = what.m_41720_()) instanceof EncodedPatternItem)) {
            return null;
        }
        EncodedPatternItem encodedPatternItem = (EncodedPatternItem)item;
        return encodedPatternItem.decode(what, level, tryRecovery);
    }
}

